// ====================================================================
// PICK EXPIRED BLOCK — MSG_BUFFER housekeeping
// MSG_BUFFER bersifat append-only => ts naik seiring nomor baris =>
// baris kadaluarsa (paling lama) SELALU blok kontigu di bagian atas
// (mulai baris 2). Jadi cukup 1x delete range (hemat kuota API).
//
// RETENTION_MS HARUS > MAX_AGE_MS (30 mnt) di node "Cek_user_status".
// Baris > 30 mnt tidak pernah dipakai untuk merge, jadi 2 jam aman.
// ====================================================================
const RETENTION_MS = 2 * 60 * 60 * 1000; // 2 jam
const cutoff = Date.now() - RETENTION_MS;

const rows = $input.all()
  .map(i => i.json)
  .filter(r => r && r.row_number !== undefined && Number(r.row_number) >= 2)
  .sort((a, b) => Number(a.row_number) - Number(b.row_number)); // menaik (atas -> bawah)

if (!rows.length) {
  console.log('🧹 MSG_BUFFER kosong / hanya header — tidak ada yang dihapus.');
  return [];
}

// Hitung run kontigu baris kadaluarsa mulai dari baris teratas.
// Berhenti di baris pertama yang MASIH segar atau ts-nya tidak valid
// (defensif: jangan pernah hapus baris yang tak bisa dipastikan umurnya).
let count = 0;
for (const r of rows) {
  const ts = Number(r.ts);
  const valid = Number.isFinite(ts) && ts > 0;
  if (valid && ts < cutoff) {
    count++;
  } else {
    if (!valid) {
      console.warn(`⚠️ Baris ${r.row_number} ts tidak valid ("${r.ts}") — stop, tidak hapus lebih jauh.`);
    }
    break;
  }
}

if (count === 0) {
  console.log('🧹 Tidak ada baris berumur > 2 jam — buffer sudah ramping.');
  return [];
}

const startRow = Number(rows[0].row_number); // normalnya 2
console.log(`🧹 Hapus ${count} baris kadaluarsa: baris ${startRow}..${startRow + count - 1}.`);
return [{ json: { startRow, count } }];
